def load(n):return json.load(open(root/n))
def save(n,x):(root/n).write_text(json.dumps(x,indent=2)+'\n')
def matrices(t):return [[[int(x.strip()) for x in row.split('&')] for row in body.split(r'\\')] for body in re.findall(r'\\begin\{bmatrix\}(.*?)\\end\{bmatrix\}',t,re.S)]
rs=load('independent-samples.json'); shape_counts=Counter(); cases=Counter(); scope_errors=[]; witnesses=[]
for r in rs:
 q=r['question'];s=q[':question/worked-solution']
 if q[':question/difficulty']!=':question.difficulty/easy':scope_errors.append('difficulty')
 for f in q[':question/answer-fields']:
  m=matrices(f[':answer-field/key'])[0];shape_counts[f'{len(m)}x{len(m[0])}']+=1
  if not(3<=len(m)<=5 and 3<=len(m[0])<=6):scope_errors.append('shape')
  if any(type(x)is not int or abs(x)>9 for row in m for x in row):scope_errors.append('value')
  p=[next((j for j,x in enumerate(row) if x),None) for row in m]
  z=any(x is None and any(y is not None for y in p[i+1:]) for i,x in enumerate(p))
  nz=[x for x in p if x is not None];bad=any(a>=b for a,b in zip(nz,nz[1:]))
  key=('both' if z and bad else 'zero' if z else 'equal' if any(a==b for a,b in zip(nz,nz[1:])) else 'left' if bad else 'valid')
  cases[key]+=1
 # Validate explicit pivot-equality/left witnesses from solutions independently.
 for letter,j,col,x,relation,letter2,i,col2,y in re.findall(r'leading entry \$([abc])_\{(\d)(\d)\}=(-?\d+)\$ is (in the same column as|to the left of) the leading entry \$([abc])_\{(\d)(\d)\}=(-?\d+)\$',s):
  m=next(matrices(f[':answer-field/key'])[0] for f in q[':question/answer-fields'] if f[':answer-field/key'].startswith('$'+letter.upper()+'='))
  j,col,x,i,col2,y=map(int,(j,col,x,i,col2,y))
  ok=letter==letter2 and i<j and m[j-1][col-1]==x and x!=0 and all(v==0 for v in m[j-1][:col-1]) and m[i-1][col2-1]==y and y!=0 and all(v==0 for v in m[i-1][:col2-1]) and (col==col2 if relation.startswith('in') else col<col2)
  witnesses.append(ok)
save('scope-results.json',{'records':len(rs),'shape_counts':dict(shape_counts),'structural_cases':dict(cases),'scope_errors':scope_errors,'pivot_witnesses_checked':len(witnesses),'pivot_witness_failures':sum(not x for x in witnesses),'judgment':'Three ordinary matrices; integer leading-entry recognition using exactly the two lesson conditions. Changes preserve elementary workload and do not introduce row operations, reduced echelon conditions, or augmented-matrix conventions. Fixed bank shapes are conservative profiles, not classifiers: all seven nonempty subsets observed per profile.'})
